#pragma once
#include "Prelude.h"

namespace finals_core {
template <class T>
vector<pair<T, T>> merge_intervals(vector<pair<T, T>> a) {
	for (auto [l, r] : a) assert(l <= r);
	sort(a.begin(), a.end());
	vector<pair<T, T>> out;
	for (auto [l, r] : a) {
		if (l == r) continue;
		if (out.empty() || out.back().second < l)
			out.push_back({l, r});
		else
			out.back().second = max(out.back().second, r);
	}
	return out;
}
} // namespace finals_core
